import copy

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

def create_point(x, y):
    """Create a new Point object."""
    return Point(x, y)

def replace_point(pt, **changes):
    """Replace attributes of a Point object with new values."""
    return copy.replace(pt, **changes)
